using Next = std::function<Response(Request&)>;
using Filter = std::function<Response(Request&, const Next&)>;

Next build(std::vector<Filter> fs, Next target) {
    for (auto it = fs.rbegin(); it != fs.rend(); ++it)
        target = [f = *it, next = std::move(target)](Request& r) { return f(r, next); };
    return target;   // build(filters, target)(req) runs: filter1 -> ... -> target -> back
}

